      bganim = 0,
      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      sentence = "With the excuse that I was gathering footage, I told my friend that I would stay here for a stretch. Although I had bought myself some time, I was in a real conundrum.",
