      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      sentence = "And so I would try bringing back pastries for him every so often. At first, Victor wouldn't so much as look at them, until one day, I realized that a green bean cake I'd brought back had a piece missing.",
